763	export async function serverAction(serverId: string, action: string): Promise<{ error?: string } | void> {
764	  // Returns `{ error }` for anything the CUSTOMER can act on, so ServerControls
765	  // can render it — a `throw` here reaches the browser as Next's redacted generic
766	  // error, discarding the specific, actionable message (e.g. "Delete your data
767	  // volume(s) before reinstalling"). Only genuinely-impossible states still throw.
768	  const { user, server } = await ownedServer(serverId);
769	  const allowed: Record<string, "START" | "STOP" | "REBOOT" | "REINSTALL" | "DELETE"> = {
770	    start: "START",
771	    stop: "STOP",
772	    reboot: "REBOOT",
773	    reinstall: "REINSTALL",
774	    delete: "DELETE",
775	  };
776	  const type = allowed[action];
777	  if (!type) throw new Error("Invalid action"); // not reachable from the UI — a real bug if it happens
778	  if (server.status === "SUSPENDED" && user.role !== "ADMIN") {
779	    return { error: "This server is suspended. Settle the outstanding balance to control it again." };
780	  }
781	
782	  // A reinstall wipes the whole VM, including any block-storage volume the VM
783	  // owns (Proxmox `qm destroy --purge` frees every disk for that vmid).
784	  //
785	  // Count volumes by `serverId` ALONE, never by `status: "ATTACHED"`. Detaching
786	  // deliberately keeps `serverId` set so the volume can be re-attached
787	  // (worker/volumes.ts) — the disk stays owned by this vmid as an `unusedN`
788	  // entry, and PVE's destroy_vm frees unused disks too (include_unused => 1).
789	  // Filtering on ATTACHED therefore missed the worst case: customer fills a
790	  // volume, clicks Detach (the UI promises "Data is preserved."), clicks
791	  // Reinstall — both guards see zero attached volumes, and the purge takes the
792	  // data with it. `reinstallToOs` in actions-server-lifecycle.ts always counted
793	  // by serverId; this path did not. That asymmetry was the bug.
794	  if (type === "REINSTALL") {
795	    const pinnedVolumes = await db.volume.count({ where: { serverId } });
796	    if (pinnedVolumes > 0) {
797	      return {
798	        error:
799	          "Delete your data volume(s) before reinstalling — a reinstall wipes the whole server, and that includes detached volumes still assigned to it. Open Volumes first.",
800	      };
801	    }
802	  }
803	
804	  const pending = await db.job.count({
805	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
806	  });
807	  // Was a silent `return`: the customer clicked Start and nothing happened, ever,
808	  // with no explanation. Tell them why.
809	  if (pending > 0) return { error: "Another operation is already running on this server. Wait for it to finish." };
810	
811	  if (type === "DELETE") {
812	    await db.server.update({ where: { id: serverId }, data: { status: "DELETING" } });
813	  }
814	  await db.job.create({ data: { type, serverId } });
815	  await audit(user.id, `server.${action}`, serverId);
816	  if (type === "DELETE") redirect(user.role === "ADMIN" ? "/admin/servers" : "/dashboard");
817	  revalidatePath(`/dashboard/servers/${serverId}`);
818	}
