/**
 * Where a family stores the RCON credentials, and how to read them.
 *
 * Two sources, discriminated by `source`:
 *  - "file": read a config file on the guest (minecraft/cs2/palworld — the
 *    password is written into a config file the game itself reads).
 *  - "docker-env": read the docker CONTAINER's own `--name`d process env via
 *    `docker inspect` (ark/arkasa/tf2/l4d2/projectzomboid). Verified live
 *    2026-09-24 (see the per-family research this session ran against each
 *    image's real Dockerfile/entrypoint) that this is not just simpler but,
 *    for ARK and ARK: Survival Ascended, the ONLY option: `hermsi/ark-server`
 *    converts `ADMIN_PASSWORD` into an `ark_ServerAdminPassword=` arkmanager
 *    key that becomes an unrecorded ShooterGameServer launch argument — it is
 *    never written to GameUserSettings.ini on disk, so a file-based reader
 *    could never find it no matter what path it searched. The other three
 *    families (tf2/l4d2/projectzomboid) do also persist their password to a
 *    file, but "docker-env" is used uniformly for all five: it is sourced
 *    straight from each family's own `docker run -e ...` in prisma/seed-wave*
 *    (the real setup script, not a guessed on-disk path), and matches the
 *    single already-published RCON port that image's `-p` mapping exposes.
 */
type FileRconConfig = {
  source: "file";
  /** Config-file path candidates to try first (absolute). */
  candidates: string[];
  /** Roots to bounded-`find` under if none of the candidates exist. */
  findRoots: string[];
  /** File name to find. */
  findName: string;
  /** File format. */
  kind: "properties" | "palworld-ini";
  /** Key that gates RCON being on (value compared case-insensitively to true/1). */
  enableKey?: string;
  /** Key holding the RCON password. */
  passwordKey: string;
  /** Key holding the RCON port (falls back to `defaultPort`). */
  portKey?: string;
  /** Port used when the file does not specify one. */
  defaultPort: number;
};

type DockerEnvRconConfig = {
  source: "docker-env";
  /** The container's own `--name` from its `docker run` invocation (compile-time
   *  constant, sourced from the family's real setupScript in prisma/seed-wave*.ts —
   *  never guessed). */
  containerName: string;
  /** The docker `-e KEY=...` env var name the setup script sets the RCON/admin
   *  password from (compile-time constant, same provenance as above). */
  passwordEnvKey: string;
  /** Fixed RCON port this family's image publishes (compile-time constant, from
   *  the real `-p` mapping — see GAME_JOIN_PORT_OVERRIDE in lib/games.ts, which
   *  documents the same port for the same reason). */
  port: number;
};

type RconConfig = FileRconConfig | DockerEnvRconConfig;

