//    `-v host:container` bind mounts in each game's setupScript. DayZ is NOT
//    here — see lib/games.ts comment.
//
//    RCON upgraded 2026-09-24 for arkasa/tf2/l4d2 (real per-family research,
//    not reverse-engineered — see each entry's own comment); soulmask stays
//    "none" — its only admin port (18888/tcp) is bound to the CONTAINER's own
//    loopback (verified live 2026-09-08, see its GAME_PORT comment in
//    lib/games.ts), so it is unreachable from the host's 127.0.0.1 regardless
//    of protocol — no amount of RCON wiring fixes a port nothing outside the
//    container's netns can ever dial. dst/vintagestory/necesse have no
//    evidence of a Source-RCON wire and stay "none". ──
// ARK: Survival Ascended — verified 2026-09-24: jsknnr/ark-ascended-server's
// own entrypoint.sh uses the gorcon rcon-cli binary directly against a live
// ASA server (issuing Saveworld/DoExit on start/stop) — real operational
// proof of genuine Source RCON, not a claim. Port 27020/tcp (RCON_PORT env,
// matches this platform's own -e RCON_PORT='27020' in
// prisma/seed-wave4-games.ts), separate from the 7777/udp game port. Same as
// ARK:SE, the password (`SERVER_ADMIN_PASSWORD`) is baked into the launch
// command rather than written to GameUserSettings.ini, so this reads it back
// off the docker container's env. List/kick/ban commands are the same verbs
// as ARK:SE (confirmed still true for ASA, which identifies players by EOS ID
// instead of Steam ID — the command syntax itself is unchanged) EXCEPT ASA
// has no confirmed BanPlayer arg format difference, so the same template is
// used; the id itself is whatever ListPlayers reports (EOS ID), validated by
// the same allowlist as every other family's kick/ban id.
arkasa: {
  family: "arkasa",
  label: "ARK: Survival Ascended",
  serviceHints: ["arkasa", "ark-ascended", "ark-survival-ascended"],
  dataRoots: ["/opt/arkasa"],
  rcon: "source",
  rconConfig: { source: "docker-env", containerName: "arkasa", passwordEnvKey: "SERVER_ADMIN_PASSWORD", port: 27020 },
  listCommand: "ListPlayers",
  kickCommand: "KickPlayer %s",
  banCommand: "BanPlayer %s",
},
// Soulmask: see the Wave 4 block comment above — 18888/tcp is loopback-bound
// INSIDE the container, so no transport reaches it regardless of protocol.
soulmask: { family: "soulmask", label: "Soulmask", serviceHints: ["soulmask"], dataRoots: ["/opt/soulmask"], rcon: "none" },
dst: { family: "dst", label: "Don't Starve Together", serviceHints: ["dst", "dontstarvetogether"], dataRoots: ["/opt/dst"], rcon: "none" },
vintagestory: { family: "vintagestory", label: "Vintage Story", serviceHints: ["vintagestory", "vintage-story"], dataRoots: ["/opt/vintagestory"], rcon: "none" },
necesse: { family: "necesse", label: "Necesse", serviceHints: ["necesse"], dataRoots: ["/opt/necesse"], rcon: "none" },
// TF2/L4D2 are Valve's own SRCDS binary — genuine Source RCON is not in doubt
// (verified 2026-09-24 against each image's real README: cm2network/tf2 sets
// SRCDS_RCONPW, left4devops/l4d2 sets RCON_PASSWORD; both publish 27015 as
// BOTH tcp+udp with RCON on the tcp side, same shape as gmod/cs2/sdtd above).
tf2: {
  family: "tf2",
  label: "Team Fortress 2",
  serviceHints: ["tf2", "tf2-server"],
  dataRoots: ["/opt/tf2"],
  rcon: "source",
  rconConfig: { source: "docker-env", containerName: "tf2", passwordEnvKey: "SRCDS_RCONPW", port: 27015 },
  listCommand: "status",
  kickCommand: "kick %s",
  banCommand: "banid 0 %s",
},
l4d2: {
