/**
 * Read a docker container's own env (`docker inspect --format '{{json
 * .Config.Env}}'`) and pull out one `KEY=value` entry. `containerName` is
 * always a compile-time constant from a `RconConfig` literal (never customer
 * input), passed through `shq`. Returns null if the container, the env var, or
 * docker itself isn't found/readable — never throws.
 */
async function readDockerEnvValue(conn: Client, containerName: string, key: string): Promise<string | null> {
  const { stdout, code } = await exec(
    conn,
    `docker inspect ${shq(containerName)} --format '{{json .Config.Env}}' 2>/dev/null`,
    QUICK_TIMEOUT_MS
  );
  if (code !== 0) return null;
  let env: unknown;
  try {
    env = JSON.parse(stdout.trim());
  } catch {
    return null;
  }
  if (!Array.isArray(env)) return null;
  const prefix = `${key}=`;
  const line = env.find((e): e is string => typeof e === "string" && e.startsWith(prefix));
  return line ? line.slice(prefix.length) : null;
}

/**
 * Read a game server's RCON credentials over SSH — either out of its own
 * config file (`source: "file"`) or out of its docker container's own env
 * (`source: "docker-env"`, see RconConfig's doc comment for why some families
 * need this instead). The password is used ONLY as a Source RCON packet body
 * downstream — never a shell argument — and the port is parsed to an integer
 * (`parsePort`)/a compile-time constant, so neither value can inject anywhere.
 */
export async function readRconCreds(conn: Client, spec: GameControlSpec): Promise<RconCreds> {
  const cfg = spec.rconConfig;
  if (spec.rcon !== "source" || !cfg) {
    return { ok: false, reason: `Remote console is not available for ${spec.label}.` };
  }

  if (cfg.source === "docker-env") {
    const password = await readDockerEnvValue(conn, cfg.containerName, cfg.passwordEnvKey);
    if (!password) return { ok: false, reason: `No RCON password is configured for ${spec.label} yet.` };
    if (password.length > 256) return { ok: false, reason: "RCON password in the container's config looks malformed." };
    return { ok: true, port: cfg.port, password };
  }

  const path = await remoteLocateFile(conn, cfg.candidates, cfg.findRoots, cfg.findName);
  if (!path) return { ok: false, reason: `Could not find ${spec.label}'s config file to read RCON settings.` };
  const text = await readRemoteText(conn, path);
  if (text == null) return { ok: false, reason: `Could not read ${spec.label}'s config file.` };

  const map = cfg.kind === "palworld-ini" ? parsePalworldIni(text) : parseFlatConfig(text);

  if (cfg.enableKey) {
    const en = (map[cfg.enableKey.toLowerCase()] ?? "").toLowerCase();
    if (en !== "true" && en !== "1" && en !== "on") {
      return { ok: false, reason: `RCON is not enabled in ${spec.label}'s config — enable it and restart to use the console.` };
    }
  }
  const password = map[cfg.passwordKey.toLowerCase()] ?? "";
  if (!password) return { ok: false, reason: `No RCON password is set in ${spec.label}'s config.` };
  if (password.length > 256) return { ok: false, reason: "RCON password in the config looks malformed." };

  const port = cfg.portKey ? parsePort(map[cfg.portKey.toLowerCase()]) ?? cfg.defaultPort : cfg.defaultPort;
  return { ok: true, port, password };
}

