 * "probably-unjoinable NAT servers" — each verified against the game's own
 * official docs/wiki (not guessed; see the per-entry citation below and the
 * research working notes referenced from lib/game-control.ts). Two corrections
 * the research turned up vs. the audit's own hypothesis, worth recording:
 *  - Sons of the Forest's real GamePort is 8766 (matches the existing
 *    GAME_PORT entry) — NOT 9700 as guessed; the two EXTRA ports are 27016
 *    (QueryPort) and 9700 (BlobSyncPort), confirmed against the community
 *    dedicated-server config field names AND that the server self-checks all
 *    three and refuses to start if any is unreachable.
 *  - ARK's 7778/udp is real but its official wiki frames it as Steam P2P
 *    advertising ("in-game browser advertising"), not a hard join requirement
 *    — forwarded anyway (defensible, zero cost, matches what most hosts do)
 *    but flagged medium-confidence rather than proven-required like the rest.
 *
 * DELIBERATELY INCOMPLETE: gmod/unturned/factorio (27015-27017 range) and eco/
 * empyrion/stationeers (27015-27016 or 30000-30003 ranges) still publish more
 * than their single joinPortFor() port and have NOT been individually verified
 * — not added here without that same live/documented verification first (a
 * wrong guess here creates the same class of bug this table exists to fix).
 */
const GAME_EXTRA_JOIN_PORTS: Partial<Record<GameFamily, { port: number; protocol: "tcp" | "udp" }[]>> = {
  valheim: [
    { port: 2457, protocol: "udp" },
    { port: 2458, protocol: "udp" },
  ],
  // Satisfactory — satisfactory.wiki.gg (official wiki), verified 2026-09-24:
  // "Port 8888 (TCP): Game traffic, Reliable messaging" — "If you have not
  // correctly forwarded the reliable messaging port, players can initiate a
  // connection but will be perpetually stuck on the 'loading' screen." Both
  // 7777/tcp and 7777/udp are published by the image; the wiki does not split
  // them the way Funcom does for Conan, so both stay forwarded alongside the
  // required 8888/tcp.
  satisfactory: [
    { port: 7777, protocol: "udp" },
    { port: 8888, protocol: "tcp" },
  ],
  // The Isle (Evrima) — theisle.info's own hosting guide, verified 2026-09-24:
  // 10000/tcp is the "Queue Port", used whenever the server's queue system is
  // enabled (commonly on by default) so a player waiting for a full server can
  // actually hold their place — part of the real join path, not cosmetic.
  theisle: [{ port: 10000, protocol: "tcp" }],
  // Sons of the Forest — Endnight's own dedicated-server config field names
  // (GamePort=8766, QueryPort=27016, BlobSyncPort=9700), cross-verified
  // against the Steam Community dedicated-server guide, 2026-09-24: the
  // server checks all three ports on startup and refuses to start if any is
  // unreachable, so both extras are hard requirements, not extras in the
  // "nice to have" sense.
  sonsoftheforest: [
    { port: 27016, protocol: "udp" },
    { port: 9700, protocol: "udp" },
  ],
  // The Forest — command-line parameter names confirm each port's role
  // (-servergameport 27015, -serverqueryport 27016, -serversteamport 8766),
  // verified 2026-09-24 against the long-standing Steam Community setup guide:
  // 8766/udp registers the server with Steam at all (without it the server is
  // unreachable/unresolvable), 27016/udp is the query port the client's join
  // handshake also uses. 27015/udp (the primary) is already joinPortFor's port.
  theforest: [
    { port: 27016, protocol: "udp" },
    { port: 8766, protocol: "udp" },
  ],
  // Squad — verified 2026-09-24: 27165/udp is the query port, part of the
  // Unreal/Steamworks OnlineSubsystem join handshake itself (client pings the
  // query port before `open steam`), not just server-browser listing. 15000/udp
  // is the "beacon" port — Epic's own Online Beacon docs describe this exact
  // mechanism as used for "reserving a spot in a game session" / "querying...
  // before joining", i.e. genuinely part of the join/queue path on a busy
  // server, not cosmetic. (Squad's RCON port 21114/tcp is unrelated — see
  // lib/game-control.ts for that story.)
  squad: [
    { port: 27165, protocol: "udp" },
    { port: 15000, protocol: "udp" },
  ],
  // ARK: Survival Evolved — ark.wiki.gg (official community wiki), verified
  // 2026-09-24: 7778/udp is "Peer port (always Game port +1)", used for
  // "Steam P2P protocol for in-game browser advertising". The wiki does not
  // state a normal join hard-fails without it (medium confidence vs. the
  // proven-required entries above), but it costs nothing to forward and many
  // real hosts do so defensively — included on that basis.
  ark: [{ port: 7778, protocol: "udp" }],
  // Project Zomboid — pzwiki.net (official wiki), quoted directly, verified
  // 2026-09-24: "Project Zomboid dedicated servers require the following open
  // ports to successfully connect to clients: 16261 UDP, 16262 UDP - Direct
  // Connection Port." 16262 (UDPPort) is the RakNet direct-connect channel;
  // without it a client falls back to the Steam relay at best (a degraded
  // path, not a substitute for a NAT-forwarded direct connection).
  projectzomboid: [{ port: 16262, protocol: "udp" }],
};

