if (server.osTemplate.setupScript) {
  // Translate the customer's checkout-time variant choice (Server.gameVariant)
  // into the actual install command BEFORE wrapping it into a systemd unit —
  // see applyGameVariant for why this substitution didn't exist until now.
  const scriptWithVariant = applyGameVariant(server.osTemplate.setupScript, server.osTemplate.family, server.gameVariant);
  // Same gap, generalized: the customer's checkout-time gameplay VALUES
  // (Server.gameConfig — e.g. DST's Klei cluster TOKEN, required for the
  // server to start at all) were captured and stored but never substituted
  // into the setupScript either, so the box always booted with the
  // template's static (usually blank) default. See applyGameConfigEnv.
  const scriptWithConfig = applyGameConfigEnv(
    scriptWithVariant,
    server.osTemplate.family,
    server.gameConfig as Record<string, unknown> | null,
  );
  // Minecraft's image tag is the ONE customization value that isn't a
  // `-e KEY=...` env var, so applyGameConfigEnv above never reaches it —
  // see applyMinecraftJavaImage's own comment for the live incident this
  // fixes (every Minecraft server provisioned on a hardcoded :java21
  // regardless of chosen VERSION). No-op for every other family.
  const scriptWithJavaImage = applyMinecraftJavaImage(
    scriptWithConfig,
    server.osTemplate.family,
    server.gameConfig as Record<string, unknown> | null,
  );
  // Per-server secrets a static catalog row can never hold for real (see
  // applyGameControlSecrets) — Palworld's ADMIN_PASSWORD doubles as the RCON
  // auth secret the player-list feature depends on, so every server needs
  // its own freshly generated value, never the catalog's shared placeholder.
  // Rust's RUST_RCON_PASSWORD is the same shape of gap, found 2026-09-10: the
  // placeholder didn't exist until this fix, so RCON (published on a public
  // port) fell back to the image's own well-known default password.
  const scriptWithSecrets =
    server.osTemplate.family === "palworld"
      ? applyGameControlSecrets(scriptWithJavaImage, { ADMIN_PASSWORD: generatePassword() })
      : server.osTemplate.family === "rust"
        ? applyGameControlSecrets(scriptWithJavaImage, { RUST_RCON_PASSWORD: generatePassword() })
        : server.osTemplate.family === "cs2"
          ? applyGameControlSecrets(scriptWithJavaImage, { CS2_RCONPW: generatePassword() })
          : scriptWithJavaImage;
  // Game images install as a bare `docker run -d` with no systemd unit, which
  // the game control panel (systemctl-based) can never see or manage — wrap it
  // in a generated unit so start/stop/restart/backup/logs actually work. See
  // wrapDockerGameService for the full story; a no-op for non-game templates.
  setup.push(wrapDockerGameService(scriptWithSecrets, server.osTemplate.family));
}

