// Translates the customer's checkout-time variant/config choices, applies
// per-server secrets, and wraps the whole thing in a systemd unit so the
// game control panel can see/manage it — see buildGameSetupScript's own
// comment. No-op (returns null) for a non-game template.
const gameSetup = buildGameSetupScript(server);
if (gameSetup) setup.push(gameSetup);

