"use client";

import { useState, useTransition } from "react";
import { reinstallGame } from "@/lib/actions-game-control";

/**
 * Danger Zone: "Wipe & reinstall" — the game-panel counterpart to
 * components/customer/ReinstallOs.tsx (VPS-level reinstall), same "type a
 * word to confirm" + window.confirm discipline, adapted for a game-only
 * re-provision that never touches the underlying VPS/VM.
 *
 * Ships wipe+reinstall of the SAME game only — full "change game" (switching
 * a running server to a different family) is a real, larger feature
 * (different OsTemplate/GamePlan/ports/RCON, a disk-footprint check) that is
 * intentionally NOT built here; see worker/game-control.ts's gameReinstall
 * doc comment. The copy below says so explicitly rather than implying more
 * than this does.
 */
export function GameReinstall({
  gameLabel,
  disabled,
}: {
  gameLabel: string;
  disabled?: boolean;
}) {
  const [open, setOpen] = useState(false);
  const [confirmText, setConfirmText] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [done, setDone] = useState(false);
  const [pending, start] = useTransition();

  const confirmed = confirmText.trim().toUpperCase() === "WIPE";

  if (done) {
    return (
      <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/[0.06] px-3 py-2.5 text-xs text-emerald-200">
        Reinstall queued — you&apos;ll get a notification once {gameLabel} is back up. The Activity tab shows progress.
      </div>
    );
  }

  return (
    <div className="rounded-lg border border-red-500/20 bg-red-500/[0.03] p-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <p className="text-sm font-semibold text-red-200">Wipe &amp; reinstall {gameLabel}</p>
          <p className="mt-0.5 text-xs text-slate-400">
            Erases the world/save data and reinstalls a fresh {gameLabel} server on this same VPS.
            The VPS itself, its IP, and SSH access are not touched.
          </p>
        </div>
        {!open && (
          <button className="btn-secondary py-1.5" onClick={() => setOpen(true)} disabled={pending || disabled}>
            Wipe &amp; reinstall
          </button>
        )}
      </div>

      {open && (
        <div className="mt-4 space-y-3">
          <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-300">
            <span className="font-semibold">This permanently erases the world/save data.</span> Take a
            backup first (Manage → Worlds) if you want to keep anything. Only {gameLabel} itself is
            reinstalled — this cannot switch the server to a different game.
          </div>

          <label className="block text-sm">
            <span className="mb-1.5 block font-medium">
              Type <span className="font-mono text-red-300">WIPE</span> to confirm
            </span>
            <input
              className="input"
              value={confirmText}
              disabled={pending || disabled}
              onChange={(e) => {
                setConfirmText(e.target.value);
                setError(null);
              }}
              placeholder="WIPE"
              autoComplete="off"
            />
          </label>

          <div className="flex flex-wrap items-center gap-3">
            <button
              className="btn-danger"
              disabled={!confirmed || pending || disabled}
              onClick={() => {
                if (!window.confirm(`Wipe and reinstall ${gameLabel} on this server? This permanently erases the world/save data and cannot be undone.`)) return;
                start(async () => {
                  setError(null);
                  const res = await reinstallGame("", confirmText);
                  if (res?.error) setError(res.error);
                  else {
                    setConfirmText("");
                    setOpen(false);
                    setDone(true);
                  }
                });
              }}
            >
              {pending ? "Queueing reinstall…" : "Wipe & reinstall"}
            </button>
            <button className="text-xs text-slate-500 hover:text-slate-300" onClick={() => setOpen(false)} disabled={pending}>
              Cancel
            </button>
          </div>

          {error && <p className="text-sm text-red-400">{error}</p>}
        </div>
      )}
    </div>
  );
}

