// -----------------------------------------------------------------------
// dockerContainerNameFrom / dockerHostMountsFrom (2026-09-24) — the parsers
// gameReinstall (worker/game-control.ts) uses to find the REAL container to
// `docker rm -f` and the REAL host directory(ies) to wipe, sourced straight
// from each family's own real setupScript (never guessed). Real setupScript
// strings below, copied from prisma/seed-wave*-games.ts.
// -----------------------------------------------------------------------

const CONAN_SCRIPT =
  'curl -fsSL https://get.docker.com | sh && docker run -d --name conan -p 7777:7777/udp -p 7777:7777/tcp -p 7778:7778/udp -p 27015:27015/udp -e GAME_INSTANCE_NAME=nxeon -e GAME_SERVER_NAME="Nxeon Conan Server" -e GAME_SERVER_PASSWORD="" -v /opt/conan/game:/conanexiles -v /opt/conan/config:/conanexiles_config --restart unless-stopped melle2/conanexiles-ds:latest';

const THEISLE_SCRIPT =
  'curl -fsSL https://get.docker.com | sh && mkdir -p /opt/theisle && chown -R 1000:1000 /opt/theisle && docker run -d --name theisle --restart unless-stopped --stop-timeout 30 -p 7777:7777/tcp -p 7777:7777/udp -p 10000:10000/tcp -e steambranch=\'evrima\' -e updateonstart=\'true\' -v /opt/theisle:"/home/steam/Steam/steamapps/common/The Isle Dedicated Server" ghcr.io/auhrus/theisleevrima:latest';

test("dockerContainerNameFrom extracts the real --name from a docker run -d command", () => {
  assert.equal(dockerContainerNameFrom(MC_SCRIPT), "mc");
  assert.equal(dockerContainerNameFrom(CONAN_SCRIPT), "conan");
  assert.equal(dockerContainerNameFrom(THEISLE_SCRIPT), "theisle");
});

test("dockerContainerNameFrom returns null for a script with no docker run -d --name", () => {
  assert.equal(dockerContainerNameFrom("apt-get install -y nginx"), null);
});

test("dockerHostMountsFrom extracts every -v HOST path, single and multiple", () => {
  assert.deepEqual(dockerHostMountsFrom(MC_SCRIPT), ["/opt/mc"]);
  assert.deepEqual(dockerHostMountsFrom(CONAN_SCRIPT), ["/opt/conan/game", "/opt/conan/config"]);
});

test("dockerHostMountsFrom isolates the host path even when the container side is quoted-with-spaces", () => {
  // The Isle's real script quotes the CONTAINER side ("...The Isle Dedicated
  // Server") because it contains spaces — must not confuse the parser about
  // where the (unquoted, space-free) HOST path ends.
  assert.deepEqual(dockerHostMountsFrom(THEISLE_SCRIPT), ["/opt/theisle"]);
});

test("dockerHostMountsFrom refuses anything not shaped like /opt/<family>[/subdir] — never a broad path", () => {
  assert.deepEqual(dockerHostMountsFrom("docker run -d --name x -v /:/data -v /opt:/data2 -v /etc:/data3 busybox"), []);
});

test("dockerHostMountsFrom de-duplicates a path mounted twice", () => {
  assert.deepEqual(dockerHostMountsFrom("docker run -d --name x -v /opt/x:/a -v /opt/x:/b busybox"), ["/opt/x"]);
});

