// these tests pin that the extraction changed nothing observable.
// -----------------------------------------------------------------------

test("buildGameSetupScript matches wrapDockerGameService's own output for a family with no secrets", () => {
  const server = { osTemplate: { setupScript: MC_SCRIPT, family: "minecraft" }, gameVariant: null, gameConfig: null };
  const out = buildGameSetupScript(server);
  assert.equal(out, wrapDockerGameService(MC_SCRIPT, "minecraft"));
  // The systemd unit + docker create rewrite really happened, not a passthrough.
  assert.match(out!, /docker create --name mc/);
  assert.match(out!, /systemctl enable --now minecraft/);
});

test("buildGameSetupScript reapplies the CURRENT gameVariant/gameConfig, not stale ones", () => {
  const server = { osTemplate: { setupScript: MC_SCRIPT, family: "minecraft" }, gameVariant: "paper", gameConfig: null };
  const out = buildGameSetupScript(server);
  assert.match(out!, /-e TYPE=PAPER/);
});

test("buildGameSetupScript mints a FRESH secret for palworld on every call (rotates, never reuses)", () => {
  const PALWORLD_SCRIPT =
    "curl -fsSL https://get.docker.com | sh && docker run -d --name palworld -p 8211:8211/udp -p 25575:25575/tcp -v /opt/palworld:/palworld -e PLAYERS=16 -e RCON_ENABLED=True -e RCON_PORT=25575 -e ADMIN_PASSWORD= --restart unless-stopped thijsvanloef/palworld-server-docker";
  const server = { osTemplate: { setupScript: PALWORLD_SCRIPT, family: "palworld" }, gameVariant: null, gameConfig: null };
  const out1 = buildGameSetupScript(server);
  const out2 = buildGameSetupScript(server);
  const pw1 = /-e ADMIN_PASSWORD='([^']*)'/.exec(out1!)?.[1];
  const pw2 = /-e ADMIN_PASSWORD='([^']*)'/.exec(out2!)?.[1];
  assert.ok(pw1 && pw1.length > 0, "a real secret was generated");
  assert.notEqual(pw1, pw2, "two builds must never mint the same secret");
});

test("buildGameSetupScript returns null when the template has no setupScript at all", () => {
  const server = { osTemplate: { setupScript: null, family: "minecraft" }, gameVariant: null, gameConfig: null };
  assert.equal(buildGameSetupScript(server), null);
});

