test("buildGameSetupScript matches wrapDockerGameService's own output for a non-minecraft family with no secrets", () => {
  // rust has no VERSION/java-image substitution to complicate the comparison —
  // isolates just the wrap step this assertion cares about.
  const RUST_SCRIPT =
    "curl -fsSL https://get.docker.com | sh && docker run -d --name rust -p 28015:28015/udp -p 28016:28016 -v /opt/rust:/steamcmd/rust -e RUST_RCON_PASSWORD= --restart unless-stopped didstopia/rust-server";
  const server = { osTemplate: { setupScript: RUST_SCRIPT, family: "rust" }, gameVariant: null, gameConfig: null };
  const out = buildGameSetupScript(server);
  // Can't assert full equality (RUST_RCON_PASSWORD gets a fresh secret), but the
  // wrap step itself (docker create + systemd unit) must be byte-identical
  // once that one substituted line is normalized away.
  const wrapped = wrapDockerGameService(RUST_SCRIPT, "rust");
  const normalize = (s: string) => s.replace(/RUST_RCON_PASSWORD='[^']*'/, "RUST_RCON_PASSWORD=X");
  assert.equal(normalize(out!), normalize(wrapped).replace("RUST_RCON_PASSWORD=", "RUST_RCON_PASSWORD=X"));
  assert.match(out!, /docker create --name rust/);
  assert.match(out!, /systemctl enable --now rust/);
});

test("buildGameSetupScript also applies the Minecraft java-image substitution (not just the wrap step)", () => {
  const server = { osTemplate: { setupScript: MC_SCRIPT, family: "minecraft" }, gameVariant: null, gameConfig: null };
  const out = buildGameSetupScript(server);
  // No VERSION in gameConfig -> falls back to the 1.21.1 default -> java21,
  // matching applyMinecraftJavaImage's own documented default behavior.
  assert.match(out!, /itzg\/minecraft-server:java21/);
  assert.match(out!, /docker create --name mc/);
  assert.match(out!, /systemctl enable --now minecraft/);
});

